$$
\int \frac {d x}{x \sqrt {a + b x}} = \frac {1}{\sqrt {a}} \ln \left| \frac {\sqrt {a + b x} - \sqrt {a}}{\sqrt {a + b x} + \sqrt {a}} \right| + C, (a > 0);
$$

$$
\int \frac {d x}{x \sqrt {a + b x}} = \frac {2}{\sqrt {- a}} \arctan \sqrt {\frac {a + b x}{- a}} + C, (a <   0);
$$

$$
\int \frac {d x}{x ^ {2} \sqrt {a + b x}} = - \frac {\sqrt {a + b x}}{a x} - \frac {b}{2 a} \int \frac {d x}{x \sqrt {a + b x}};
$$

$$
\int \frac {\sqrt {a + b x} d x}{x} = 2 \sqrt {a + b x} + a \int \frac {d x}{x \sqrt {a + b x}};
$$

$$
\begin{array}{l} \int x ^ {m} \sqrt {2 a x - x ^ {2}} d x = - \frac {x ^ {m - 1} \left(2 a x + x ^ {2}\right) ^ {\frac {3}{2}}}{m + 1} + \frac {(2 m + 1) a}{m} \int x ^ {m - 1} \sqrt {2 a x - x ^ {2}} d x; \\ \int \frac {x ^ {m} d x}{\sqrt {2 a x - x ^ {2}}} = - \frac {x ^ {m - 1} \sqrt {2 a x - x ^ {2}}}{m} + \frac {(2 m - 1) a}{m} \int \frac {x ^ {m - 1} d x}{\sqrt {2 a x - x ^ {2}}}; \\ \int \frac {\sqrt {2 a x - x ^ {2}}}{x ^ {m}} d x = - \frac {(2 a x - x ^ {2}) ^ {\frac {3}{2}}}{(2 m - 3) a x ^ {m}} + \frac {m - 3}{(2 m - 3) a} \int \frac {\sqrt {2 a x + x ^ {2}}}{x ^ {m - 1}} d x; \\ \int \frac {d x}{x \sqrt {2 a x - x ^ {2}}} = - \frac {\sqrt {2 a x - x ^ {2}}}{a x} + C. \end{array}
$$

5. Tích phân của hàm lượng giác

$$
\int \sin x d x = - \cos x + C;
$$

$$
\int \cos x d x = \sin x + C;
$$

$$
\int \sin^ {2} x d x = \frac {x}{2} - \frac {1}{4} \sin 2 x + C;
$$

$$
\int \cos^ {2} x d x = \frac {x}{2} + \frac {1}{4} \sin 2 x + C;
$$

$$
\int \sin^ {3} x d x = \frac {1}{2} \cos^ {3} x - \cos x + C;
$$

$$
\int \cos^ {3} x d x = \sin x - \frac {1}{3} \sin^ {3} x + C;
$$

$$
\int \sin^ {n} x d x = - \frac {1}{n} \sin^ {n - 1} x \cos x + \frac {n - 1}{n} \int \sin^ {n - 2} x d x;
$$
